// Strict validator for decision cards (cards/decision/*.json).
//
// Unlike validate-drills.js this runs AJV in strict mode against the schema
// exactly as generated by the app (no $schema delete, no validateSchema:false),
// with ajv-keywords' uniqueItemProperties for unique option ids.
//
// Fails on: invalid JSON, schema errors, filename !== id, duplicate id across
// files, duplicate legacy_id across files, a current card whose id is listed
// in the retired-id file, and the quality lints in scripts/lib/card-lints.js:
// format (2-space JSON plus trailing newline), field-cap (per-field length
// caps), sentence-length (max words per sentence), no-url (no links or domains
// in any string), and the tag rules (tag-unknown, tag-duplicate, tag-count).
//
// Warns (fails with BALANCE_LINTS_STRICT or --strict-balance): option-balance,
// tags-missing, and the deck-share rules (deck-best-longest, deck-best-first,
// deck-best-shortest).
//
// Frozen ids (ADR 0009 D-06..D-08): with --base <git-ref> (CI passes the PR's
// base branch) each card file that exists at <ref> is compared with the
// working tree:
//   - an existing card's option ids and legacy_id may not change (its id is
//     pinned by filename === id);
//   - an existing card may only be removed if its id is added to the
//     retired-id file, so the id is never reused for different content;
//   - ids may not be removed from the retired-id file;
//   - an option's grade may not change unless the card's rev increases, and
//     rev may never decrease (rev-bump, D-20).
// Renaming a card is therefore "retire the old id + add a new card".
//
// Usage: node scripts/validate-cards.js [--dir <path>] [--retired <path>] [--base <git-ref>] [--strict-balance]
import { execFileSync } from 'child_process';
import { existsSync, readFileSync, readdirSync, statSync } from 'fs';
import { basename, join, resolve } from 'path';
import Ajv2020 from 'ajv/dist/2020.js';
import addKeywords from 'ajv-keywords';
import {
  lintCard,
  lintDeck,
  checkFormat,
  checkRevBump,
  isFailure,
  BALANCE_LINTS_STRICT,
} from './lib/card-lints.js';

function argValue(name) {
  const i = process.argv.indexOf(name);
  if (i === -1) return undefined;
  const v = process.argv[i + 1];
  if (v === undefined || v.startsWith('--')) {
    console.error(`Missing value for ${name}`);
    process.exit(1);
  }
  return v;
}

const dirArg = argValue('--dir');
const cardsDir = dirArg
  ? resolve(process.cwd(), dirArg)
  : new URL('../cards/decision', import.meta.url).pathname;
const schemaPath = new URL('../docs/schema/card.schema.json', import.meta.url).pathname;
const repoRoot = new URL('..', import.meta.url).pathname;
const retiredArg = argValue('--retired');
const retiredPath = retiredArg
  ? resolve(process.cwd(), retiredArg)
  : new URL('../cards/decision.retired.json', import.meta.url).pathname;
// Repo-relative paths read from the base ref.
const BASE_CARDS_DIR = 'cards/decision';
const BASE_RETIRED_PATH = 'cards/decision.retired.json';
const baseRef = argValue('--base');
const strictBalance = BALANCE_LINTS_STRICT || process.argv.includes('--strict-balance');

// unicode: false makes maxLength/minLength count UTF-16 code units, matching
// zod's .max()/.min() in the app. AJV's default counts code points, so strings
// with astral-plane characters (most emoji) would pass here and then be dropped
// by the app at runtime.
const ajv = new Ajv2020({
  strict: true,
  allErrors: true,
  unicode: false,
  // AJV flags `unicode` as deprecated but still honours it; silence only that notice.
  logger: {
    log: console.log.bind(console),
    warn: (...args) => {
      if (!String(args[0]).startsWith('DEPRECATED: option unicode')) console.warn(...args);
    },
    error: console.error.bind(console),
  },
});
addKeywords(ajv, ['uniqueItemProperties']);

const schema = JSON.parse(readFileSync(schemaPath, 'utf8'));
const validate = ajv.compile(schema);

if (!existsSync(cardsDir) || !statSync(cardsDir).isDirectory()) {
  console.error(`FAIL no cards found in ${cardsDir}`);
  process.exit(1);
}

const files = readdirSync(cardsDir)
  .filter((f) => f.endsWith('.json'))
  .sort();

if (files.length === 0 && !dirArg) {
  console.error(`FAIL no cards found in ${cardsDir}`);
  process.exit(1);
}

let failed = 0;
let warnings = 0;
const seenIds = new Map(); // id -> file
const seenLegacy = new Map(); // legacy_id -> file
const current = new Map(); // id -> parsed card (schema-valid cards, lint failures included)

/** Parse a retired-id list: a JSON array of unique card id strings. */
function parseRetired(text, label) {
  let list;
  try {
    list = JSON.parse(text);
  } catch (e) {
    throw new Error(`${label}: invalid JSON — ${e.message}`);
  }
  if (!Array.isArray(list) || !list.every((x) => typeof x === 'string' && x.length > 0)) {
    throw new Error(`${label}: must be a JSON array of card id strings`);
  }
  if (new Set(list).size !== list.length) {
    throw new Error(`${label}: contains duplicate ids`);
  }
  return list;
}

let retired = [];
if (existsSync(retiredPath)) {
  try {
    retired = parseRetired(readFileSync(retiredPath, 'utf8'), basename(retiredPath));
  } catch (e) {
    console.error(`FAIL ${e.message}`);
    failed++;
  }
}
const retiredSet = new Set(retired);

console.log(
  strictBalance
    ? 'Balance lints: strict'
    : 'Balance lints: warn only (set BALANCE_LINTS_STRICT or pass --strict-balance)',
);

/** Print a lint issue as FAIL or WARN; returns true when it fails. */
function reportIssue(label, issue) {
  if (isFailure(issue, strictBalance)) {
    console.error(`FAIL ${label}: [${issue.rule}] ${issue.message}`);
    return true;
  }
  console.warn(`WARN ${label}: [${issue.rule}] ${issue.message}`);
  warnings++;
  return false;
}

for (const file of files) {
  const filePath = join(cardsDir, file);
  let data;
  let text;
  try {
    text = readFileSync(filePath, 'utf8');
    data = JSON.parse(text);
  } catch (e) {
    console.error(`FAIL ${file}: invalid JSON — ${e.message}`);
    failed++;
    continue;
  }

  if (!validate(data)) {
    console.error(`FAIL ${file}:`);
    for (const err of validate.errors) {
      console.error(`  ${err.instancePath || '/'} ${err.message}`);
    }
    failed++;
    continue;
  }

  const expectedId = basename(file, '.json');
  if (data.id !== expectedId) {
    console.error(`FAIL ${file}: id "${data.id}" does not match filename "${expectedId}"`);
    failed++;
    continue;
  }

  if (seenIds.has(data.id)) {
    console.error(`FAIL ${file}: duplicate id "${data.id}" (also in ${seenIds.get(data.id)})`);
    failed++;
    continue;
  }
  seenIds.set(data.id, file);

  if (retiredSet.has(data.id)) {
    console.error(`FAIL ${file}: id "${data.id}" is retired and may not be reused`);
    failed++;
    continue;
  }

  if (data.legacy_id !== undefined) {
    if (seenLegacy.has(data.legacy_id)) {
      console.error(
        `FAIL ${file}: duplicate legacy_id "${data.legacy_id}" (also in ${seenLegacy.get(data.legacy_id)})`,
      );
      failed++;
      continue;
    }
    seenLegacy.set(data.legacy_id, file);
  }

  // Record the card before linting so the deck lints and the --base checks
  // still see a card that fails a lint.
  current.set(data.id, data);

  const issues = [checkFormat(text), ...lintCard(data)].filter(Boolean);
  let lintFailed = false;
  for (const issue of issues) {
    if (reportIssue(file, issue)) lintFailed = true;
  }
  if (lintFailed) {
    failed++;
    continue;
  }
  console.log(`OK   ${file}`);
}

for (const issue of lintDeck([...current.values()])) {
  const deckIssue = { ...issue, message: `${issue.path}: ${issue.message}` };
  if (reportIssue('deck', deckIssue)) failed++;
}

/** Run git in the repo root; returns stdout, or throws with git's message. */
function git(args) {
  return execFileSync('git', args, { cwd: repoRoot, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
}

function showAtBase(path) {
  try {
    return git(['show', `${baseRef}:${path}`]);
  } catch {
    return null;
  }
}

const optionIds = (card) => (card.options ?? []).map((o) => o.id).sort();

if (baseRef) {
  try {
    git(['rev-parse', '--verify', '--quiet', `${baseRef}^{commit}`]);
  } catch {
    console.error(`FAIL --base ${baseRef}: not a commit in this repository (fetch it first)`);
    process.exit(1);
  }

  const baseFiles = git(['ls-tree', '--name-only', baseRef, `${BASE_CARDS_DIR}/`])
    .split('\n')
    .map((p) => basename(p))
    .filter((f) => f.endsWith('.json'))
    .sort();

  const baseRetiredText = showAtBase(BASE_RETIRED_PATH);
  let baseRetired = [];
  if (baseRetiredText !== null) {
    try {
      baseRetired = parseRetired(baseRetiredText, `${BASE_RETIRED_PATH} at ${baseRef}`);
    } catch (e) {
      console.warn(`WARN ${e.message}; skipping the append-only check`);
    }
  }
  for (const id of baseRetired) {
    if (!retiredSet.has(id)) {
      console.error(`FAIL ${basename(retiredPath)}: retired id "${id}" was removed (the list is append-only)`);
      failed++;
    }
  }

  let compared = 0;
  for (const file of baseFiles) {
    const id = basename(file, '.json');
    const baseText = showAtBase(`${BASE_CARDS_DIR}/${file}`);
    let before;
    try {
      before = JSON.parse(baseText);
    } catch {
      console.warn(`WARN ${file}: unreadable at ${baseRef}; skipping frozen-id check`);
      continue;
    }

    if (!files.includes(file)) {
      if (!retiredSet.has(id)) {
        console.error(
          `FAIL ${file}: card "${id}" was removed or renamed; add "${id}" to ${basename(retiredPath)} to retire it (ids are never reused)`,
        );
        failed++;
      }
      continue;
    }

    const after = current.get(id);
    if (!after) continue; // already reported as invalid above
    compared++;

    const beforeOpts = optionIds(before);
    const afterOpts = optionIds(after);
    if (beforeOpts.join('\n') !== afterOpts.join('\n')) {
      console.error(
        `FAIL ${file}: option ids are frozen (was [${beforeOpts.join(', ')}], now [${afterOpts.join(', ')}]); reword the text, keep the ids`,
      );
      failed++;
    }
    if (before.legacy_id !== after.legacy_id) {
      console.error(
        `FAIL ${file}: legacy_id is frozen (was ${JSON.stringify(before.legacy_id)}, now ${JSON.stringify(after.legacy_id)})`,
      );
      failed++;
    }
    const revIssue = checkRevBump(before, after);
    if (revIssue) {
      console.error(`FAIL ${file}: [rev-bump] ${revIssue}`);
      failed++;
    }
  }
  console.log(`\nFrozen-id and rev check against ${baseRef}: ${baseFiles.length} base card(s), ${compared} compared.`);
}

if (failed > 0) {
  console.error(`\n${failed} file(s) failed validation (${warnings} warning(s)).`);
  process.exit(1);
}
console.log(`\nAll ${files.length} card(s) valid (${warnings} warning(s)).`);
